package com.aistudyassistance.backend.dsa; import java.time.*; import jakarta.persistence.*;
@Entity @Table(name="dsa_problems") public class DsaProblem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String title;@Column(nullable=false)private String platform;@Column(nullable=false)private String difficulty;@Column(nullable=false)private String topic;@Column(nullable=false)private String status;@Column(name="time_taken_minutes",nullable=false)private int timeTakenMinutes;@Column(name="revision_status",nullable=false)private String revisionStatus;private String notes;@Column(name="solved_at")private LocalDate solvedAt;@Column(name="created_at")private OffsetDateTime createdAt;@Column(name="updated_at")private OffsetDateTime updatedAt;protected DsaProblem(){} public DsaProblem(DsaRequest r){apply(r);}@PrePersist void create(){createdAt=updatedAt=OffsetDateTime.now();}@PreUpdate void update(){updatedAt=OffsetDateTime.now();}void apply(DsaRequest r){title=r.title().trim();platform=r.platform();difficulty=r.difficulty();topic=r.topic();status=r.status();timeTakenMinutes=r.timeTakenMinutes();revisionStatus=r.revisionStatus();notes=r.notes();solvedAt=r.solvedAt();}public Long getId(){return id;}public String getTitle(){return title;}public String getPlatform(){return platform;}public String getDifficulty(){return difficulty;}public String getTopic(){return topic;}public String getStatus(){return status;}public int getTimeTakenMinutes(){return timeTakenMinutes;}public String getRevisionStatus(){return revisionStatus;}public String getNotes(){return notes;}public LocalDate getSolvedAt(){return solvedAt;}}
